import {hasCloudConfig,getSession,signIn,signUp,signOut,loadCloudData,rpc,consumeAuthRedirect} from './supabase-client.js';
import {sidebar,svg,installSidebar} from './premium-sidebar.js';
import {titles,activeAssignments,permitted,menuFor,routeAllowed} from './access.js';

const ADMIN_PORTAL = typeof window !== 'undefined' && /\/admin\.html$/i.test(window.location?.pathname || '');
const portal=ADMIN_PORTAL?'admin':/\/staff\.html$/i.test(window.location?.pathname || '')?'staff':'patient';
const STAFF_PORTAL = typeof window !== 'undefined' && (/\/staff\.html$/i.test(window.location?.pathname || '')||ADMIN_PORTAL);
const UI={page:STAFF_PORTAL?'account':'home',role:STAFF_PORTAL?'staff':'patient',mode:'demo',authTab:'login',dept:'GENERAL',room:'GENERAL_101',staffSearch:'',filter:'ALL',authBusy:false,authError:'',syncError:'',remote:null,modal:null,showMenu:false,waiting:{},assignmentId:null,updated:Date.now()};
const storeKey='mediqueue_web_demo_v1';
const dateVN=()=>new Intl.DateTimeFormat('sv-SE',{timeZone:'Asia/Ho_Chi_Minh',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
const displayDate=()=>new Intl.DateTimeFormat('vi-VN',{dateStyle:'full',timeZone:'Asia/Ho_Chi_Minh'}).format(new Date());
const fmtTime=(d)=>d?new Date(d).toLocaleTimeString('vi-VN',{hour:'2-digit',minute:'2-digit'}):'—';
const icons={grid:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',ticket:'<path d="M2 9a3 3 0 0 0 0 6v3a2 2 0 0 0 2 2h16a2 2 0 0 0 2-2v-3a3 3 0 0 1 0-6V6a2 2 0 0 0-2-2H4a2 2 0 0 0-2 2z"/><path d="M13 5v2m0 4v2m0 4v2"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l4 3"/>',bell:'<path d="M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9"/><path d="M10 21h4"/>',users:'<path d="M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2"/><circle cx="9" cy="7" r="4"/><path d="M22 21v-2a4 4 0 0 0-3-3.87M16 3.13a4 4 0 0 1 0 7.75"/>',activity:'<path d="M3 12h4l3-8 4 16 3-8h4"/>',briefcase:'<rect x="3" y="7" width="18" height="14" rx="2"/><path d="M8 7V5a2 2 0 0 1 2-2h4a2 2 0 0 1 2 2v2M3 12h18"/>',heart:'<path d="M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.6a5.5 5.5 0 0 0 0-7.8z"/>',plus:'<path d="M12 5v14M5 12h14"/>',arrow:'<path d="M5 12h14m-7-7 7 7-7 7"/>',check:'<path d="m5 12 4 4L19 6"/>',alert:'<circle cx="12" cy="12" r="10"/><path d="M12 7v6m0 4h.01"/>',logout:'<path d="M9 21H5a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h4"/><path d="m16 17 5-5-5-5m5 5H9"/>',menu:'<path d="M4 6h16M4 12h16M4 18h16"/>',settings:'<circle cx="12" cy="12" r="3"/><path d="M12 2v2m0 16v2m10-10h-2M4 12H2m17.07-7.07-1.42 1.42M6.35 17.65l-1.42 1.42m14.14 0-1.42-1.42M6.35 6.35 4.93 4.93"/>',search:'<circle cx="11" cy="11" r="7"/><path d="m20 20-4-4"/>',hospital:'<path d="M4 21V7a2 2 0 0 1 2-2h12a2 2 0 0 1 2 2v14M1 21h22M10 21v-5h4v5M9 10h6m-3-3v6"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M7 3v4m10-4v4M3 10h18"/>',qr:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><path d="M16 14v3h3v4m-5-2h2m3-6h2m-6 8h2"/>',pause:'<path d="M8 4h3v16H8zm7 0h3v16h-3z"/>',play:'<path d="m7 4 14 8-14 8z"/>',refresh:'<path d="M20 7v5h-5M4 17v-5h5"/><path d="M5 9a8 8 0 0 1 14-2M19 15A8 8 0 0 1 5 17"/>',shield:'<path d="M12 22s8-4 8-10V5l-8-3-8 3v7c0 6 8 10 8 10"/><path d="m9 12 2 2 4-4"/>',copy:'<rect x="8" y="8" width="12" height="12" rx="2"/><path d="M16 8V6a2 2 0 0 0-2-2H6a2 2 0 0 0-2 2v8a2 2 0 0 0 2 2h2"/>',lock:'<rect x="4" y="10" width="16" height="11" rx="2"/><path d="M8 10V7a4 4 0 0 1 8 0v3"/>',clipboard:'<rect x="5" y="4" width="14" height="18" rx="2"/><rect x="9" y="2" width="6" height="4" rx="1"/><path d="M9 12h6m-6 4h6"/>',trend:'<path d="m3 17 6-6 4 4 7-8m-6 0h6v6"/>',user:'<circle cx="12" cy="8" r="4"/><path d="M4 22v-2a8 8 0 0 1 16 0v2"/>',checkcircle:'<circle cx="12" cy="12" r="10"/><path d="m7 12 3 3 7-7"/>',chevron:'<path d="m9 18 6-6-6-6"/>',zap:'<path d="m13 2-9 12h7l-1 8 10-12h-7z"/>'};
function I(n,size=19){return `<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[n]||icons.grid}</svg>`;}
const E=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const DEPTS=[{code:'GENERAL',title:'Khám tổng quát',prefix:'T',room:'Phòng 101',icon:'hospital'},{code:'INTERNAL',title:'Nội tổng hợp',prefix:'N',room:'Phòng 102',icon:'heart'},{code:'PEDIATRICS',title:'Nhi khoa',prefix:'P',room:'Phòng 103',icon:'activity'}];
const ROOMS=[{id:'GENERAL_101',department_code:'GENERAL',title:'Phòng 101',is_available:true},{id:'GENERAL_104',department_code:'GENERAL',title:'Phòng 104',is_available:true},{id:'INTERNAL_102',department_code:'INTERNAL',title:'Phòng 102',is_available:true},{id:'INTERNAL_105',department_code:'INTERNAL',title:'Phòng 105',is_available:true},{id:'PEDIATRICS_103',department_code:'PEDIATRICS',title:'Phòng 103',is_available:true},{id:'PEDIATRICS_106',department_code:'PEDIATRICS',title:'Phòng 106',is_available:true}];
const rand=()=>globalThis.crypto?.randomUUID?.()||`demo-${Date.now()}-${Math.random().toString(36).slice(2)}`;
const now=()=>new Date().toISOString();
function seedDemo(){let prev=localStorage.getItem(storeKey);if(prev){try{const obj=JSON.parse(prev);if(obj.day===dateVN()&&obj.tickets?.length)return obj;}catch{}}
const fake=['Minh Anh','Bảo Ngọc','Hoàng Minh','Thu Hà','Gia Huy','Ngọc Mai','Đức Anh','Thanh Hương','Khánh Linh','Trọng Đức','Bảo Long','Nhật Nam'];let ix=0,uid=1,tickets=[];
for(const d of DEPTS){for(let n=1;n<=9;n++){const name=fake[ix++%fake.length];const status=n<=3?'COMPLETED':n===4?'SERVING':n===5?'CALLED':'WAITING';const room=ROOMS.filter(x=>x.department_code===d.code)[(n-1)%2]; tickets.push({id:uid++,date_key:dateVN(),department_code:d.code,queue_number:n,patient_id:`demo-${ix}`,patient_name:name,is_priority:n===8,status,created_at:now(),called_at:n<=5?now():null,started_at:n<=4?now():null,completed_at:n<=3?now():null,room_id:room.id,checked_in_at:now(),qr_nonce:rand(),recall_count:0});}}
// One owner ticket to demonstrate the patient experience.
tickets.push({id:uid,date_key:dateVN(),department_code:'GENERAL',queue_number:10,patient_id:'demo-me',patient_name:'Khách trải nghiệm',is_priority:false,status:'WAITING',created_at:now(),room_id:'GENERAL_101',checked_in_at:now(),qr_nonce:rand(),recall_count:0});
return {day:dateVN(),tickets,rooms:ROOMS,departments:DEPTS,paused:[],myName:'Khách trải nghiệm'};
}
let demo=seedDemo();function persist(){localStorage.setItem(storeKey,JSON.stringify(demo));try{new BroadcastChannel('mq-demo').postMessage({type:'updated'});}catch{}}
function verifiedAccess(){
 if(UI.mode==='cloud')return UI.remote?.access||null;
 return {role:STAFF_PORTAL?'staff':'patient',is_hospital_admin:false,assignments:STAFF_PORTAL?[{id:'preview-only',job_title:'department_lead',department_code:'GENERAL',room_id:null,valid_from:'2000-01-01T00:00:00Z',valid_to:'2100-01-01T00:00:00Z'}]:[]};
}
function assignment(){return activeAssignments(verifiedAccess()).find(a=>a.id===UI.assignmentId)||activeAssignments(verifiedAccess())[0];}
function can(task,t){return UI.mode==='demo'?STAFF_PORTAL:permitted(verifiedAccess(),task,t?.department_code||UI.dept,t?.room_id||UI.room,assignment()?.id);}
function tickets(){const all=UI.mode==='cloud'?(UI.remote?.tickets||[]):demo.tickets;const a=assignment();return UI.mode==='cloud'&&portal==='staff'?all.filter(t=>t.department_code===a?.department_code&&(!a.room_id||t.room_id===a.room_id)):all;}
function departments(){const all=UI.mode==='cloud'?(UI.remote?.departments||[]):DEPTS;const a=assignment();return UI.mode==='cloud'&&portal==='staff'?all.filter(d=>d.code===a?.department_code):all;}
function rooms(){const all=UI.mode==='cloud'?(UI.remote?.rooms||[]):demo.rooms;const a=assignment();return UI.mode==='cloud'&&portal==='staff'?all.filter(r=>r.department_code===a?.department_code&&(!a.room_id||r.id===a.room_id)):all;}
function role(){return UI.mode==='cloud'?(UI.remote?.profile?.role||'patient'):UI.role;}
function isStaff(){return ['staff','admin'].includes(role());}
function ownTickets(){return UI.mode==='cloud'?tickets().filter(t=>t.patient_id===getSession()?.user?.id):tickets().filter(t=>t.patient_id==='demo-me');}
function dept(code){return departments().find(d=>d.code===code)||DEPTS.find(d=>d.code===code)||{title:code,prefix:'?' };}
function label(t){return `${dept(t.department_code).prefix}${String(t.queue_number).padStart(3,'0')}`;}
function liveRoom(roomId){if(UI.mode==='cloud')return UI.remote?.roomLive?.find(r=>r.room_id===roomId)||{waiting_count:0};const inRoom=tickets().filter(t=>t.room_id===roomId);const active=inRoom.find(t=>['CALLED','SERVING'].includes(t.status));return {waiting_count:inRoom.filter(t=>t.status==='WAITING').length,current_label:active?label(active):null,current_status:active?.status||null};}
function isPaused(code){if(UI.mode==='cloud')return !!UI.remote?.live?.find(v=>v.department_code===code)?.is_paused;return demo.paused.includes(code);}
function liveDept(code){if(UI.mode==='cloud')return UI.remote?.live?.find(v=>v.department_code===code)||{waiting_count:0};const tt=tickets().filter(t=>t.department_code===code);const active=tt.find(t=>['CALLED','SERVING'].includes(t.status));return {waiting_count:tt.filter(t=>t.status==='WAITING').length,current_label:active?label(active):null};}
const statuses={WAITING:['Đang chờ','wait'],CALLED:['Đã gọi','called'],SERVING:['Đang khám','serving'],COMPLETED:['Hoàn tất','completed'],SKIPPED:['Đã bỏ lượt','skipped']};
function badge(s){let [a,b]=statuses[s]||[s,'wait'];return `<span class="tag tag-${b}">${E(a)}</span>`;}
function toast(m,type=''){let el=document.createElement('div');el.className=`toast ${type}`;el.innerHTML=`${I(type?'alert':'checkcircle')}<span>${E(m)}</span>`;let box=document.getElementById('toasts');box.append(el);setTimeout(()=>el.remove(),4600);}
let navigation=[];
function move(page){if(!routeAllowed(page,verifiedAccess(),portal,assignment()?.id)){toast('Bạn chưa được cấp quyền cho chức năng này.','error');return;}UI.page=page;window.history?.replaceState?.(null,'','#'+page);window.scrollTo({top:0,behavior:'smooth'});render();}
function renderShell(){
 navigation=menuFor(verifiedAccess(),portal,assignment()?.id);
 document.body?.classList?.add('workspace');document.body?.classList?.toggle('admin-workspace',ADMIN_PORTAL);
 const pageTitle=navigation.find(x=>x[0]===UI.page)?.[1]||'Tài khoản';
 return `<header class="work-header"><button class="mq-sidebar-toggle mq-mobile-trigger" data-sidebar="open" aria-label="Mở menu" aria-controls="mq-drawer" aria-expanded="false">${svg('menu')}</button><a class="work-brand" href="./index.html"><img src="assets/mark.svg" width="37" height="37" alt=""><span><b>MediQueue</b><small>HOSPITAL OPERATIONS</small></span></a><div class="work-header-right"><span class="demo-indicator">${UI.mode==='demo'?'DEMO · DỮ LIỆU GIẢ':'MEDIQUEUE-DEV · TÀI KHOẢN THỬ'}</span><button class="btn btn-ghost btn-sm" data-action="refresh" aria-label="Làm mới dữ liệu">${I('refresh',16)}</button></div></header><div class="work-shell">${sidebar({access:verifiedAccess(),portal,currentRoute:UI.page,profile:UI.remote?.profile,assignmentId:assignment()?.id,mode:UI.mode})}<main class="work-main"><div class="work-content" id="content"><div class="page-crumb">MediQueue <span>›</span> ${portal==='patient'?'Cổng bệnh nhân':ADMIN_PORTAL?'Điều hành toàn viện':'Cổng nhân viên'} <span>›</span><strong>${E(pageTitle)}</strong></div>${UI.syncError?`<div class="alert" role="alert">${E(UI.syncError)}</div>`:''}${renderPage()}<p class="bottom-disclaimer">MediQueue-Dev · ${UI.mode==='demo'?'Dữ liệu mô phỏng; không cấp quyền thật.':'Dữ liệu theo quyền truy cập · Không dùng thông tin bệnh nhân thật.'}</p></div></main></div><button type="button" class="mq-drawer-overlay" data-sidebar="close" aria-label="Đóng menu"></button><div class="toast-container" id="toasts" aria-live="polite"></div>${UI.modal?modalHtml():''}`;
}
const title=(over,h,sub,action='')=>`<div class="headline"><div><div class="overline">${over}</div><h1>${h}</h1><p class="subtitle">${sub}</p></div>${action?`<div class="header-actions">${action}</div>`:''}</div>`;
function counts(){let tt=tickets();return {total:tt.length,waiting:tt.filter(t=>t.status==='WAITING').length,active:tt.filter(t=>['CALLED','SERVING'].includes(t.status)).length,completed:tt.filter(t=>t.status==='COMPLETED').length};}
function stats(){let k=counts();return `<div class="grid4">${[[I('ticket'),'Tổng phiếu khám',k.total,'Số lượt trong dữ liệu','bg-turq'],[I('clock'),'Đang chờ',k.waiting,'Phiếu chưa được gọi','bg-blue'],[I('activity'),'Đang phục vụ',k.active,'Tất cả phòng khám','bg-orange'],[I('checkcircle'),'Đã hoàn tất',k.completed,'Số lượt hoàn thành','bg-violet']].map(([icon,s,n,note,cls])=>`<div class="card stat"><div class="st-top"><span class="st-label">${s}</span><span class="stat-icon ${cls}">${icon}</span></div><div class="num">${n}</div><div class="note">${note}</div></div>`).join('')}</div>`;}
function deptCard(d){const v=liveDept(d.code);return `<div class="card dept"><div class="dept-top"><div class="dept-symbol">${I(d.icon||'hospital',18)}</div><span class="tiny-status ${isPaused(d.code)?'paused':''}">${isPaused(d.code)?'Tạm dừng':'Đang tiếp nhận'}</span></div><h3>${E(d.title)}</h3><p>${rooms().filter(r=>r.department_code===d.code).length} phòng khám</p><div class="dept-foot"><div><span>Số đang chờ</span><div><strong>${v.waiting_count||0}</strong> <span>phiếu</span></div></div><button class="small-link" data-page="book">Lấy số ${I('arrow',12)}</button></div></div>`;}
function home(){const k=counts();const owner=ownTickets().find(t=>['WAITING','CALLED','SERVING'].includes(t.status))||ownTickets()[0];const progress=k.total?Math.round(k.completed/k.total*100):0;return title('DASHBOARD · MEDIQUEUE','Chào mừng trở lại 👋','Theo dõi hoạt động khám bệnh và quản lý hàng chờ trên cùng một màn hình.',`<button class="btn btn-ghost" data-action="refresh">${I('refresh')} Làm mới</button><button class="btn btn-primary" data-page="book">${I('plus')} Lấy số ngay</button>`)+stats()+`<div class="cols2"><div><section class="hero card"><div class="hero-inner"><div><span class="hero-tag">${I('zap',13)} GIẢI PHÁP BỆNH VIỆN THÔNG MINH</span><h2>Không còn phải chờ<br/>mà không biết đến lượt.</h2><p>Đăng ký nhanh, theo dõi thời gian chờ và chủ động sắp xếp lịch trình khám bệnh.</p><button class="btn" data-page="book">Đăng ký lượt khám ${I('arrow')}</button></div><div class="big-plus">${I('plus',70)}</div></div></section><section class="sec"><div class="section-top"><h2 class="section-title">Tình trạng các khoa</h2><button class="small-link" data-page="staff">Danh sách phòng ${I('arrow',13)}</button></div><div class="dept-grid">${departments().map(deptCard).join('')}</div></section></div><div><div class="card side-panel"><div class="section-top"><h2 class="section-title">${owner?'Phiếu khám của bạn':'Tình hình hàng chờ'}</h2>${I('ticket',17)}</div>${owner?`<div class="queue-box"><div class="eyebrow">Số thứ tự của bạn</div><div class="queue-number">${label(owner)}</div><p>${E(dept(owner.department_code).title)} · ${E(rooms().find(r=>r.id===owner.room_id)?.title||'Chưa phân phòng')}</p>${badge(owner.status)}</div>`:`<div class="queue-box"><div class="eyebrow">Đang phục vụ</div><div class="queue-number">${E(liveDept('GENERAL').current_label||'—')}</div><p>Khám tổng quát</p></div>`}<div class="progress-label"><span>Tiến độ khám</span><b>${progress}%</b></div><div class="progress"><span style="width:${progress}%"></span></div><div class="today-card"><div class="mini-row"><div class="left"><div class="mini-icon">${I('checkcircle')}</div><div><strong>Đã hoàn tất</strong><small>Trong dữ liệu hiện tại</small></div></div><div class="value">${k.completed} lượt</div></div><div class="mini-row"><div class="left"><div class="mini-icon">${I('clock')}</div><div><strong>Đang chờ</strong><small>Cần được tiếp nhận</small></div></div><div class="value">${k.waiting} lượt</div></div></div><div class="panel-note">${I('shield',17)}<span>${UI.mode==='demo'?'Đây là bản thử nghiệm. Tất cả tên và phiếu trên giao diện demo là dữ liệu giả.':'Dữ liệu phiếu khám được giới hạn theo vai trò và tài khoản đăng nhập.'}</span></div></div></div></div><section class="sec card card-pad"><div class="section-top"><h2 class="section-title">Danh sách phòng khám</h2><span class="pill-outline">${rooms().length} phòng</span></div>${roomTable(rooms().slice(0,6))}</section>`;}
function roomTable(rs){return `<div class="tablewrap"><table class="table"><thead><tr><th>PHÒNG</th><th>CHUYÊN KHOA</th><th>ĐANG GỌI</th><th>CHỜ</th><th>TRẠNG THÁI</th></tr></thead><tbody>${rs.map(r=>{const v=liveRoom(r.id);return `<tr><td class="strong">${E(r.title)}</td><td>${E(dept(r.department_code).title)}</td><td class="strong">${E(v.current_label||'—')}</td><td>${v.waiting_count||0}</td><td><span class="tiny-status ${isPaused(r.department_code)?'paused':''}">${isPaused(r.department_code)?'Tạm dừng':r.is_available?'Hoạt động':'Tạm đóng'}</span></td></tr>`;}).join('')}</tbody></table></div>`;}
function book(){const disabled=UI.mode==='cloud'&&!getSession();return title('DÀNH CHO BỆNH NHÂN','Đăng ký lấy số','Chọn chuyên khoa và lấy số thứ tự trực tuyến chỉ trong vài thao tác.')+`<div class="cols2"><section class="card card-pad"><div class="section-top"><h2 class="section-title">Thông tin đăng ký</h2><span class="pill-outline">${I('shield',12)} Bảo mật</span></div><form id="bookingForm" class="stack"><label class="field">Họ và tên người khám<input type="text" name="patientName" autocomplete="name" minlength="2" maxlength="60" required placeholder="Nhập họ và tên" value="${E(UI.mode==='demo'?demo.myName:'')}"/></label><label class="field">Chuyên khoa khám<select name="department">${departments().map(d=>`<option value="${E(d.code)}" ${d.code===UI.dept?'selected':''}>${E(d.title)}</option>`).join('')}</select></label><div class="alert">${I('alert',17)}<div>Số được cấp tự động theo thứ tự. Trường hợp ưu tiên cần nhân viên y tế xác nhận; cấp cứu được xử lý theo quy trình riêng.</div></div><button class="btn btn-primary btn-wide" ${disabled?'disabled':''} type="submit">${I('ticket')} Xác nhận lấy số ${I('arrow')}</button>${disabled?'<p class="muted">Đăng nhập Supabase trước khi lấy số trên cloud.</p>':''}</form></section><aside class="card side-panel"><h2 class="section-title" style="margin-bottom:22px">Hướng dẫn lấy số</h2><div class="stack">${[['01','Chọn chuyên khoa','Chọn khoa phù hợp với nhu cầu khám.'],['02','Nhận phiếu điện tử','Hệ thống cấp số tự động, không trùng trong ngày.'],['03','Check-in tại bệnh viện','Đưa mã check-in cho nhân viên tại quầy.'],['04','Theo dõi lượt khám','Xem phòng được chỉ định và số đang gọi.']].map(([n,t,d])=>`<div class="mini-row" style="justify-content:start;align-items:flex-start"><div class="mini-icon" style="background:#e6f7f4;color:#0b8d89;font-weight:850">${n}</div><div><strong>${t}</strong><small style="line-height:1.7">${d}</small></div></div>`).join('')}</div><div class="panel-note">${I('clock')}<span>Thời gian chờ chỉ là ước tính tham khảo, có thể thay đổi theo diễn biến khám thực tế.</span></div></aside></div><section class="sec"><div class="section-top"><h2 class="section-title">Tình trạng tiếp nhận</h2></div><div class="dept-grid">${departments().map(deptCard).join('')}</div></section>`;}
function waitEstimate(t){if(t.status!=='WAITING')return null;if(UI.mode==='cloud'){return UI.waiting[t.id]||null;}const q=tickets().filter(x=>x.status==='WAITING' && (t.room_id?x.room_id===t.room_id:x.department_code===t.department_code)).sort((a,b)=>(b.is_priority?1:0)-(a.is_priority?1:0)||a.queue_number-b.queue_number);const i=q.findIndex(x=>x.id===t.id);let active=tickets().filter(x=>x.room_id===t.room_id&&['CALLED','SERVING'].includes(x.status)).length;return {queue_position:i+1,estimate_minutes:Math.max(0,(i+active)*12)};}
function track(){let mine=ownTickets().slice().reverse();return title('PHIẾU KHÁM CỦA BẠN','Theo dõi lượt khám','Thông tin phiếu khám cá nhân được cập nhật từ dữ liệu đang có.',`<button class="btn btn-primary" data-page="book">${I('plus')} Lấy số mới</button>`)+`<div class="cols2"><div>${mine.length?mine.map(t=>{const w=waitEstimate(t),room=rooms().find(r=>r.id===t.room_id);return `<div class="card ticket-card"><div class="ticket-head"><span class="overline" style="margin:0">PHIẾU KHÁM ĐIỆN TỬ</span>${badge(t.status)}</div><div class="ticket-value">${label(t)}</div><div class="meta">${E(dept(t.department_code).title)} · ${E(room?.title||'Chưa phân phòng')}<br/>Đăng ký lúc ${fmtTime(t.created_at)}</div><div class="ticket-details"><div><label>Vị trí trong hàng</label><strong>${w?.queue_position||'—'}</strong></div><div><label>Thời gian dự kiến</label><strong>${w?.estimate_minutes!=null?w.estimate_minutes+' phút':'—'}</strong></div><div><label>Check-in</label><strong>${t.checked_in_at?'Đã xác nhận':'Chưa check-in'}</strong></div></div><div class="ticket-foot"><button class="btn btn-ghost btn-sm" data-action="checkin-code" data-id="${t.id}">${I('qr',14)} Mã check-in</button>${t.status==='WAITING'?`<button class="btn btn-danger btn-sm" data-action="cancel" data-id="${t.id}">Hủy phiếu</button>`:''}<button class="btn btn-ghost btn-sm" data-action="copy-label" data-label="${label(t)}">${I('copy',14)} Sao chép số</button></div></div>`}).join(''):`<div class="empty">${I('ticket',34)}<h3>Chưa có phiếu khám</h3><p>Hãy chọn chuyên khoa và đăng ký lượt khám đầu tiên.</p><button class="btn btn-primary" data-page="book">Lấy số ngay</button></div>`}</div><aside><div class="card side-panel"><h2 class="section-title">Thông tin hữu ích</h2><div class="panel-note">${I('alert')}<span>Vị trí và thời gian ước tính có thể thay đổi khi có bệnh nhân ưu tiên hoặc bác sĩ tạm ngừng khám.</span></div><div class="today-card"><div class="mini-row"><div class="left"><span class="mini-icon">${I('bell')}</span><div><strong>Theo dõi tự động</strong><small>${UI.mode==='cloud'?'Trang làm mới định kỳ khi đang mở':'Dữ liệu cập nhật giữa các tab cùng trình duyệt'}</small></div></div></div><div class="mini-row"><div class="left"><span class="mini-icon">${I('shield')}</span><div><strong>Quyền riêng tư</strong><small>Không hiển thị hồ sơ người bệnh khác</small></div></div></div></div></div></aside></div>`;}
function staff(){if(!isStaff()){return title('DÀNH CHO NHÂN VIÊN','Điều phối hàng chờ','Chức năng nhân viên yêu cầu quyền được cấp trên máy chủ.')+`<div class="card card-pad" style="max-width:680px"><div class="empty">${I('lock',44)}<h3>Khu vực dành cho nhân viên</h3><p>${UI.mode==='demo'?'Chọn chế độ nhân viên để trải nghiệm các thao tác với dữ liệu mô phỏng.':'Bạn đang đăng nhập bằng tài khoản bệnh nhân. Vai trò do Supabase xác định; không thể đổi quyền từ giao diện.'}</p>${UI.mode==='demo'?`<button class="btn btn-primary" data-action="demo-staff">${I('shield')} Chuyển sang nhân viên demo</button>`:`<button class="btn btn-ghost" data-page="account">Xem tài khoản</button>`}</div></div>`;}
const ds=departments().filter(d=>UI.mode==='demo'||role()==='admin'||d.code===UI.remote?.profile?.department_code);if(!ds.some(d=>d.code===UI.dept)) UI.dept=ds[0]?.code||'GENERAL';const rs=rooms().filter(r=>r.department_code===UI.dept);if(!rs.some(r=>r.id===UI.room))UI.room=rs[0]?.id||'';const selected=rs.find(r=>r.id===UI.room);const v=liveRoom(UI.room);const tt=tickets().filter(t=>t.department_code===UI.dept).filter(t=>!UI.staffSearch || (label(t)+' '+t.patient_name).toLocaleLowerCase('vi').includes(UI.staffSearch.toLocaleLowerCase('vi'))).sort((a,b)=>b.queue_number-a.queue_number);
return title('BẢNG ĐIỀU PHỐI','Quản lý phòng khám','Gọi số riêng theo phòng, check-in, chuyển phòng và cập nhật trạng thái phiếu.',`<span class="role-flag">${I('shield',13)} Nhân viên</span><button class="btn btn-ghost" data-action="refresh">${I('refresh')} Làm mới</button>`)+`<section class="card card-pad"><div class="section-top"><h2 class="section-title">Chọn khoa và phòng đang làm việc</h2><span class="pill-outline">Phân quyền theo khoa</span></div><div class="form2"><label class="field">Chuyên khoa<select id="staffDept">${ds.map(d=>`<option value="${E(d.code)}" ${UI.dept===d.code?'selected':''}>${E(d.title)}</option>`).join('')}</select></label><label class="field">Phòng khám<select id="staffRoom">${rs.map(r=>`<option value="${E(r.id)}" ${UI.room===r.id?'selected':''}>${E(r.title)}</option>`).join('')}</select></label></div><div class="cta-line" style="margin-top:16px"><div class="pill-outline">${I('activity',12)} Khoa: ${isPaused(UI.dept)?'Đang tạm dừng':'Đang hoạt động'}</div><button class="btn ${isPaused(UI.dept)?'btn-outline':'btn-ghost'} btn-sm" data-action="toggle-pause">${I(isPaused(UI.dept)?'play':'pause',14)} ${isPaused(UI.dept)?'Mở lại khoa':'Tạm dừng khoa'}</button></div></section><section class="sec rooms">${rs.map(r=>{const x=liveRoom(r.id);return `<article class="card room-card"><div class="mini-row"><div class="room-icon">${I('hospital',19)}</div><span class="tiny-status ${!r.is_available?'paused':''}">${r.is_available?'Sẵn sàng':'Tạm đóng'}</span></div><div><h3 class="room-title">${E(r.title)}</h3><div class="room-dept">${E(dept(r.department_code).title)}</div></div><div class="room-count"><span>Đang gọi / khám</span><b>${E(x.current_label||'—')}</b></div><div class="room-count"><span>Bệnh nhân đang chờ</span><b>${x.waiting_count||0}</b></div><button class="btn ${UI.room===r.id?'btn-primary':'btn-ghost'} btn-wide" data-action="pick-room" data-room="${E(r.id)}">${UI.room===r.id?I('check',15):I('chevron',15)} ${UI.room===r.id?'Đang chọn phòng':'Chọn phòng'}</button></article>`;}).join('')}</section><section class="sec staff-panel"><div class="card card-pad"><div class="section-top"><h2 class="section-title">Bảng điều khiển ${E(selected?.title||'')}</h2><span class="tag tag-${v.current_status==='SERVING'?'serving':'wait'}">${v.current_label?'Đang tiếp nhận':'Sẵn sàng'}</span></div><div class="queue-box"><div class="eyebrow">Bệnh nhân hiện tại</div><div class="queue-number">${E(v.current_label||'—')}</div><p>${v.current_status==='CALLED'?'Đã gọi vào phòng':v.current_status==='SERVING'?'Đang khám':'Chưa có bệnh nhân đang gọi'}</p></div><div class="form2" style="margin-top:18px"><button class="btn btn-primary btn-wide" data-action="call-next">${I('bell')} Gọi số tiếp theo</button><button class="btn btn-ghost btn-wide" data-action="checkin-form">${I('qr')} Check-in mã</button></div><div class="panel-note">${I('shield')}<span>Chỉ gọi bệnh nhân đã check-in và được phân vào đúng phòng. Máy chủ ngăn hai lượt đang khám trong cùng một phòng.</span></div></div><aside class="card card-pad"><div class="section-top"><h2 class="section-title">Lượt khám trong khoa</h2><span class="pill-outline">${tt.length} phiếu</span></div><label class="search">${I('search',16)}<input id="staffSearch" placeholder="Tìm tên hoặc số phiếu" value="${E(UI.staffSearch)}" /></label><div class="stack" style="margin-top:14px;max-height:465px;overflow:auto">${tt.slice(0,20).map(t=>`<div class="mini-row" style="align-items:flex-start;border-bottom:1px solid #edf1f3;padding-bottom:11px"><div class="left"><span class="avatar" style="width:33px;height:33px;font-size:10px">${E(label(t).slice(0,1))}</span><div><strong>${E(label(t))} · ${E(t.patient_name)}</strong><small>${E(rooms().find(r=>r.id===t.room_id)?.title||'Chưa phân phòng')} · ${t.checked_in_at?'Đã check-in':'Chưa check-in'}</small><small>${badge(t.status)}</small></div></div><button class="btn btn-ghost btn-sm" data-action="ticket-actions" data-id="${t.id}">Xử lý</button></div>`).join('')||'<p class="muted">Không có phiếu khám phù hợp.</p>'}</div></aside></section>`;
}
function analytics(){const k=counts();const data=departments().map(d=>({name:d.title,value:tickets().filter(t=>t.department_code===d.code).length,complete:tickets().filter(t=>t.department_code===d.code&&t.status==='COMPLETED').length}));const max=Math.max(1,...data.map(d=>d.value));const pct=k.total?Math.round(k.completed/k.total*100):0;return title('BÁO CÁO · THỐNG KÊ','Phân tích hoạt động','Theo dõi tình trạng khám theo khoa và hiệu suất giải quyết lượt khám.',`<button class="btn btn-ghost" data-action="refresh">${I('refresh')} Cập nhật số liệu</button>`)+stats()+`<div class="insight-grid"><div class="card card-pad"><div class="section-top"><h2 class="section-title">Lượt khám theo chuyên khoa</h2><span class="pill-outline">${dateVN()}</span></div><div class="chart">${data.map(d=>`<div class="bar-col"><div class="bar-value">${d.value}</div><div class="bar" style="height:${Math.round(d.value/max*115)}px"></div><div class="bar-label">${E(d.name.replace('Khám ','').replace(' tổng hợp',''))}</div></div>`).join('')}</div><div class="panel-note">${I('alert')}<span>${UI.mode==='cloud'?'Số liệu hiển thị theo phạm vi truy cập của tài khoản hiện tại.':'Số liệu lấy từ bộ dữ liệu demo giả lập, không đại diện bệnh viện thực tế.'}</span></div></div><div class="card card-pad"><div class="section-top"><h2 class="section-title">Tỉ lệ hoàn thành</h2>${I('checkcircle',20)}</div><div class="big-stat">${pct}<span style="font-size:22px">%</span></div><p class="subtitle">${k.completed} trên tổng ${k.total} phiếu đã được xử lý hoàn tất.</p><div class="progress" style="height:11px;margin:19px 0"><span style="width:${pct}%"></span></div><div class="stack">${data.map(d=>`<div><div class="progress-label"><span>${E(d.name)}</span><b>${d.value?Math.round(d.complete/d.value*100):0}%</b></div><div class="progress"><span style="width:${d.value?Math.round(d.complete/d.value*100):0}%"></span></div></div>`).join('')}</div></div></div><section class="sec card card-pad"><div class="section-top"><h2 class="section-title">Tổng quan các phòng</h2></div>${roomTable(rooms())}</section>`;}
function account(){
 const s=getSession(),isCloud=UI.mode==='cloud',staff=STAFF_PORTAL;
 const portalLabel=staff?'Nhân viên & quản trị':'Bệnh nhân';
 const otherPortal=staff?'./index.html':'./staff.html';
 const otherLabel=staff?'Sang cổng bệnh nhân':'Sang cổng nhân viên / quản trị';
 let body='';
 if(isCloud && s?.user){
  body='<div class="card card-pad stack"><div class="mini-row"><div class="left"><div class="avatar">'+I('user')+'</div><div><strong>'+E(UI.remote?.profile?.display_name||s.user.email)+'</strong><small>'+E(s.user.email)+'</small></div></div><span class="role-flag">Vai trò: '+E(role())+'</span></div><div class="alert">'+I('shield')+'<span>Quyền truy cập do bệnh viện cấp tại Supabase. Không thể tự nâng cấp tài khoản.</span></div><button class="btn btn-danger" data-action="logout">'+I('logout')+' Đăng xuất</button></div>';
 } else if(isCloud) body=authForm();
 else body='<div class="card card-pad stack"><div class="section-top"><h2 class="section-title">Chế độ mô phỏng '+portalLabel+'</h2><span class="mode-pill"><span class="dot"></span> DEMO</span></div><p class="subtitle">Dữ liệu giả lưu trong trình duyệt. Không có quyền truy cập hệ thống bệnh viện thật.</p>'+(staff?'<p>Trong demo bạn có thể thử điều phối và tiếp đón. Quyền này không áp dụng lên Supabase.</p><button class="btn btn-primary" data-page="staff">Mở điều phối demo</button>':'<label class="field">Tên bệnh nhân demo<input id="demoName" value="'+E(demo.myName)+'" maxlength="60" /></label><button class="btn btn-primary" data-page="book">Lấy số khám demo</button>')+'<button class="btn btn-danger" data-action="reset-demo">Đặt lại dữ liệu giả</button></div>';
 return title('CỔNG '+(staff?'NHÂN VIÊN':'BỆNH NHÂN'),'Tài khoản '+portalLabel,'Tài khoản bệnh nhân và tài khoản nội bộ được quản lý độc lập về vai trò và quyền truy cập.')
  +'<div class="cols2"><div>'+((isCloud&&s?.user&&UI.remote?.access?.state==='awaiting_provisioning')?'<div class="alert" role="status">Chưa có phân công hợp lệ trong ca trực. Liên hệ quản trị để cấp quyền. Quản trị toàn viện yêu cầu quyền riêng và MFA.</div>':'')+body+'</div><aside class="card side-panel stack"><h2 class="section-title">Quyền truy cập</h2><div class="notice">'+I('shield',19)+'<div><b>'+(staff?'Chỉ đăng nhập, không tự đăng ký':'Tự đăng ký tài khoản bệnh nhân')+'</b><p>'+(staff?'Tài khoản staff/admin chỉ do người có thẩm quyền của bệnh viện cấp. Đăng ký công khai không tạo ra quyền nội bộ.':'Sau đăng ký, hệ thống chỉ cấp vai trò patient; không thể chọn staff hoặc admin.')+'</p></div></div><div class="notice">'+I('lock',19)+'<div><b>Backend bảo vệ dữ liệu</b><p>Supabase RLS và các hàm kiểm tra quyền ở máy chủ, không dựa vào đường dẫn website.</p></div></div><a class="btn btn-outline btn-wide" href="'+otherPortal+'">'+E(otherLabel)+'</a>'+(hasCloudConfig?'<button class="btn btn-ghost btn-wide" data-action="toggle-cloud">'+(isCloud?'Xem dữ liệu giả (DEMO)':'Quay về hệ thống CLOUD')+'</button>':'')+'<p class="muted">MediQueue-Dev chỉ sử dụng tài khoản và dữ liệu thử nghiệm.</p></aside></div>';
}
function authForm(){
 const staff=STAFF_PORTAL;
 return '<div class="card auth-card"><div class="auth-banner"><div class="round">'+I('lock',29)+'</div><h2>'+(staff?'Đăng nhập nhân viên / quản trị':UI.authTab==='login'?'Đăng nhập bệnh nhân':'Đăng ký khám bệnh')+'</h2><p>'+(staff?'Chỉ dành cho nhân viên và quản trị viên đã được cấp tài khoản.':'Đăng ký tài khoản bệnh nhân để lấy số và theo dõi lượt khám.')+'</p></div>'
 + (staff?'':'<div class="switch-tabs"><button type="button" class="'+(UI.authTab==='login'?'active':'')+'" data-action="auth-login-tab">Đăng nhập bệnh nhân</button><button type="button" class="'+(UI.authTab==='signup'?'active':'')+'" data-action="auth-signup-tab">Đăng ký bệnh nhân</button></div>')
 + (UI.authError?'<div class="alert" role="alert">'+E(UI.authError)+'</div>':'')
 + '<form id="authForm" class="stack"><label class="field">Email<input type="email" name="email" required placeholder="email@example.com" autocomplete="email"/></label><label class="field">Mật khẩu<input type="password" name="password" minlength="6" required autocomplete="'+(!staff&&UI.authTab==='signup'?'new-password':'current-password')+'" placeholder="Nhập mật khẩu"/></label><button class="btn btn-primary btn-wide" type="submit">'+I('lock',16)+' '+(staff?'Đăng nhập nội bộ':UI.authTab==='signup'?'Tạo tài khoản bệnh nhân':'Đăng nhập bệnh nhân')+'</button><p class="muted">'+(staff?'Không có nút đăng ký nhân viên. Liên hệ người quản lý bệnh viện để được cấp quyền.':UI.authTab==='signup'?'Tài khoản đăng ký chỉ có vai trò bệnh nhân. Có thể cần xác minh email.':'Không nhập dữ liệu bệnh nhân thật trong giai đoạn thử nghiệm.')+'</p></form></div>';
}

/** Hospital workflow additions. No patient names are included on public room boards. */
function board(){
 const rr=rooms().filter(r=>r.is_available);
 let total=rr.reduce((n,r)=>n+Number(liveRoom(r.id).waiting_count||0),0);
 return title('BẢNG GỌI SỐ','Bảng theo dõi khu chờ','Chỉ hiển thị số thứ tự, phòng khám và lượng đang chờ; không hiển thị thông tin định danh.','<button class="btn btn-primary" data-action="fullscreen-board">Toàn màn hình</button><button class="btn btn-ghost" data-action="refresh">Làm mới</button>')
 +'<section class="board-hero"><div><span class="board-overline">MEDIQUEUE · BẢNG HIỂN THỊ PHÒNG CHỜ</span><h2>Xin mời theo dõi số đang gọi</h2><p>Đến đúng phòng khi số thứ tự của bạn hiển thị. Trường hợp khẩn cấp liên hệ nhân viên y tế ngay.</p></div><div class="board-total"><span>ĐANG CHỜ</span><strong>'+total+'</strong></div></section>'
 +'<div class="board-grid" aria-live="polite">'+rr.map(r=>{
 const v=liveRoom(r.id);
 return '<article class="board-room"><div class="board-room-top"><div><span>'+E(dept(r.department_code).title)+'</span><h3>'+E(r.title)+'</h3></div><small class="board-state">'+(isPaused(r.department_code)?'TẠM DỪNG':'HOẠT ĐỘNG')+'</small></div><div class="board-current"><span>ĐANG GỌI / ĐANG KHÁM</span><strong>'+E(v.current_label||'—')+'</strong></div><div class="board-bottom"><span>Đang chờ</span><b>'+Number(v.waiting_count||0)+'</b></div></article>';
 }).join('')+'</div><div class="card board-help"><b>Ưu tiên cấp cứu:</b> không chờ số. '+(UI.mode==='demo'?'Đây là dữ liệu giả, chỉ để trải nghiệm.':'Số liệu cập nhật định kỳ khi trình duyệt đang mở.')+'</div>';
}
function reception(){
 if(!isStaff())return title('DÀNH CHO NHÂN VIÊN','Quầy tiếp đón','Vui lòng đăng nhập bằng tài khoản đã được cấp quyền hoặc chuyển vai trò trong chế độ demo.')+'<div class="card card-pad"><button class="btn btn-primary" data-page="account">Đi tới tài khoản</button></div>';
 const access=departments().filter(d=>UI.mode==='demo'||role()==='admin'||d.code===UI.remote?.profile?.department_code);
 if(!access.some(x=>x.code===UI.dept))UI.dept=access[0]?.code||'GENERAL';
 const list=tickets().filter(t=>t.department_code===UI.dept);
 const shown=list.filter(t=>!UI.staffSearch||(label(t)+' '+t.patient_name).toLocaleLowerCase('vi').includes(UI.staffSearch.toLocaleLowerCase('vi'))).sort((a,b)=>a.queue_number-b.queue_number);
 const totals=[['Tổng số đăng ký',list.length],['Chưa check-in',list.filter(t=>t.status==='WAITING'&&!t.checked_in_at).length],['Đã check-in',list.filter(t=>t.status==='WAITING'&&t.checked_in_at).length],['Hoàn tất',list.filter(t=>t.status==='COMPLETED').length]];
 return title('TIẾP ĐÓN BỆNH NHÂN','Quầy tiếp đón & check-in','Kiểm tra mã phiếu, xác nhận bệnh nhân đã đến và hướng dẫn vào phòng khám.','<button class="btn btn-primary" data-action="checkin-form">Check-in bằng mã</button>')
 +'<div class="grid4">'+totals.map(x=>'<div class="card stat"><div class="st-label">'+x[0]+'</div><div class="num">'+x[1]+'</div><div class="note">Theo chuyên khoa</div></div>').join('')+'</div>'
 +'<section class="card card-pad"><div class="section-top"><h2 class="section-title">Danh sách lượt khám</h2><span class="pill-outline">Dữ liệu nội bộ có phân quyền</span></div><div class="form2"><label class="field">Chuyên khoa<select id="staffDept">'+access.map(d=>'<option value="'+E(d.code)+'" '+(d.code===UI.dept?'selected':'')+'>'+E(d.title)+'</option>').join('')+'</select></label><label class="field">Tìm phiếu<input id="staffSearch" value="'+E(UI.staffSearch)+'" placeholder="Tên hoặc số phiếu"></label></div><div class="tablewrap" style="margin-top:18px"><table class="table"><thead><tr><th>SỐ</th><th>NGƯỜI ĐĂNG KÝ</th><th>TRẠNG THÁI</th><th>PHÒNG KHÁM</th><th>CHECK-IN</th></tr></thead><tbody>'+shown.map(t=>'<tr><td class="strong">'+E(label(t))+'</td><td>'+E(t.patient_name)+'</td><td>'+badge(t.status)+'</td><td>'+E(rooms().find(r=>r.id===t.room_id)?.title||'Chưa phân phòng')+'</td><td>'+(t.checked_in_at?'Đã có mặt':t.status==='WAITING'?'Chưa xác nhận':'—')+'</td></tr>').join('')+'</tbody></table></div><div class="cta-line" style="margin-top:19px"><button class="btn btn-ghost" data-page="staff">Đến bảng điều phối</button><button class="btn btn-primary" data-action="checkin-form">Check-in</button></div></section>'
 +'<div class="panel-note" style="margin-top:16px">Nhân viên phải đối chiếu đúng bệnh nhân trước khi check-in. Trường hợp cấp cứu được xử trí qua quy trình riêng, không tự động xếp theo FIFO.</div>';
}
function guide(){
 const steps=[['01','Lấy số khám','Bệnh nhân chọn chuyên khoa và lấy số trên website.'],['02','Check-in','Nhân viên đối chiếu phiếu khám và xác nhận bằng mã.'],['03','Phân phòng','Phân vào phòng cùng khoa; nhân viên điều phối có thể chuyển phòng.'],['04','Gọi số','Mỗi phòng chỉ gọi một lượt hoạt động tại một thời điểm.'],['05','Hoàn tất','Bắt đầu, kết thúc, bỏ lượt, gọi lại và cập nhật hàng chờ.'],['06','Cấp cứu','Tình huống cấp cứu phải được nhân viên y tế đánh giá và xử trí riêng.']];
 return title('QUY TRÌNH VẬN HÀNH','Hướng dẫn sử dụng','Luồng tiếp nhận bệnh nhân ngoại trú trong bản MediQueue thử nghiệm.')
 +'<div class="guide-grid">'+steps.map(x=>'<article class="card guide-step"><span class="guide-no">'+x[0]+'</span><h3>'+x[1]+'</h3><p>'+x[2]+'</p></article>').join('')+'</div><section class="card card-pad sec"><h2 class="section-title">Giới hạn của bản công khai</h2><p class="subtitle" style="margin-top:10px">Không bao gồm bệnh án điện tử, kê đơn, bảo hiểm, xét nghiệm, thanh toán, phân loại cấp cứu hay quản lý thuốc. Chưa được đánh giá để sử dụng với thông tin người bệnh thật.</p></section>';
}

function renderPage(){
 if(!routeAllowed(UI.page,verifiedAccess(),portal,assignment()?.id))UI.page='account';
 switch(UI.page){case'book':return book();case'track':return track();case'reception':return reception();case'staff':case'tasks':case'work-home':return workDashboard();case'board':return board();case'analytics':return analytics();case'guide':return guide();case'account':return account();case'admin-home':case'departments':case'access':case'admin-security':case'audit':return adminDashboard();default:return portal==='patient'?patientHome():home();}
}
function modalHtml(){const m=UI.modal;if(!m)return '';return `<div class="modal-backdrop"><div class="modal" role="dialog" aria-modal="true" aria-labelledby="modal-title"><h3 id="modal-title">${E(m.title)}</h3><p>${E(m.description||'')}</p>${m.body||''}<div class="modal-actions"><button class="btn btn-ghost" data-action="close-modal">Đóng</button>${m.confirm?`<button class="btn ${m.danger?'btn-danger':'btn-primary'}" data-action="confirm-modal">${E(m.confirm)}</button>`:''}</div></div></div>`;}
function setModal(m){UI.modal=m;render();}
function render(){document.getElementById('app').innerHTML=renderShell();}
function findTicket(id){return tickets().find(t=>String(t.id)===String(id));}
function chooseRoom(department){const choices=rooms().filter(r=>r.department_code===department&&r.is_available).sort((a,b)=>tickets().filter(t=>t.room_id===a.id&&['WAITING','CALLED','SERVING'].includes(t.status)).length-tickets().filter(t=>t.room_id===b.id&&['WAITING','CALLED','SERVING'].includes(t.status)).length);return choices[0];}
function touch(t){persist();render();return t;}
function demoChange(action,args){const my=()=>findTicket(args.p_ticket_id);let t=my();switch(action){
case 'mq_issue_ticket':{if(isPaused(args.p_department))throw Error('Khoa đang tạm dừng tiếp nhận.');let ids=tickets().filter(x=>x.department_code===args.p_department);if(!demo.myName||!args.p_name)throw Error('Vui lòng nhập họ tên.');if(ownTickets().filter(x=>['WAITING','CALLED','SERVING'].includes(x.status)).length>=3)throw Error('Tối đa 3 phiếu khám đang hoạt động.');const n=Math.max(0,...ids.map(x=>x.queue_number))+1;t={id:Math.max(0,...tickets().map(x=>x.id))+1,patient_id:'demo-me',department_code:args.p_department,queue_number:n,date_key:dateVN(),patient_name:args.p_name,status:'WAITING',is_priority:false,created_at:now(),room_id:null,checked_in_at:null,qr_nonce:rand(),request_key:args.p_request_key,recall_count:0};demo.tickets.push(t);break;}
case 'mq_cancel_my_ticket':if(!t||t.patient_id!=='demo-me'||t.status!=='WAITING')throw Error('Chỉ hủy được phiếu đang chờ của bạn.');t.status='SKIPPED';break;
case 'mq_checkin_qr':{t=tickets().find(x=>x.qr_nonce===args.p_nonce);if(!t||t.status!=='WAITING')throw Error('Mã không hợp lệ hoặc phiếu không còn chờ.');if(t.checked_in_at)throw Error('Phiếu đã check-in.');if(isPaused(t.department_code))throw Error('Khoa đang tạm dừng.');const r=chooseRoom(t.department_code);if(!r)throw Error('Không còn phòng phù hợp.');t.room_id=r.id;t.checked_in_at=now();break;}
case 'mq_assign_room':if(!t||t.status!=='WAITING'||!t.checked_in_at)throw Error('Chỉ chuyển phiếu chờ đã check-in.');if(!rooms().some(r=>r.id===args.p_room_id&&r.department_code===t.department_code))throw Error('Phòng không thuộc chuyên khoa.');t.room_id=args.p_room_id;break;
case 'mq_call_next_room':{const r=rooms().find(x=>x.id===args.p_room_id);if(!r||!r.is_available)throw Error('Phòng không hoạt động.');if(isPaused(r.department_code))throw Error('Khoa đang tạm dừng.');if(tickets().some(x=>x.room_id===r.id&&['CALLED','SERVING'].includes(x.status)))throw Error('Phòng còn lượt đang phục vụ.');t=tickets().filter(x=>x.room_id===r.id&&x.status==='WAITING'&&x.checked_in_at).sort((a,b)=>Number(b.is_priority)-Number(a.is_priority)||a.queue_number-b.queue_number)[0];if(!t)throw Error('Phòng chưa có phiếu đã check-in đang chờ.');t.status='CALLED';t.called_at=now();break;}
case 'mq_change_ticket':if(!t)throw Error('Không tìm thấy phiếu.');if(args.p_action==='START'&&t.status==='CALLED'){t.status='SERVING';t.started_at=now();}else if(args.p_action==='FINISH'&&t.status==='SERVING'){t.status='COMPLETED';t.completed_at=now();}else if(args.p_action==='SKIP'&&['WAITING','CALLED'].includes(t.status)){t.status='SKIPPED';}else if(args.p_action==='RESTORE'&&t.status==='SKIPPED'){t.status='WAITING';t.called_at=null;}else if(args.p_action==='PRIORITY'&&t.status==='WAITING'){t.is_priority=!!args.p_priority;}else throw Error('Trạng thái phiếu không cho phép thao tác này.');break;
case 'mq_recall_ticket':if(!t||t.status!=='CALLED'||t.recall_count>=3)throw Error('Không thể gọi lại phiếu này.');t.recall_count++;t.called_at=now();break;
case 'mq_set_department_pause':{const code=args.p_department;if(args.p_paused&&!isPaused(code))demo.paused.push(code);if(!args.p_paused)demo.paused=demo.paused.filter(x=>x!==code);break;}
default:throw Error('Chức năng chưa được hỗ trợ trong demo.');}
touch(t);return t;}
async function execute(name,params,success){try{if(UI.mode==='cloud'){if(!getSession())throw Error('Vui lòng đăng nhập.');await rpc(name,params);await refresh(true);}else demoChange(name,params);if(success)toast(success);return true;}catch(err){toast(err.message||String(err),'error');return false;}}
async function refresh(silent=false){try{UI.syncError='';if(UI.mode==='cloud'&&getSession()){UI.remote=await loadCloudData();UI.updated=Date.now();const ts=ownTickets().filter(t=>t.status==='WAITING');const waits=await Promise.all(ts.slice(0,12).map(t=>rpc('mq_my_wait_info',{p_ticket_id:t.id}).then(r=>[t.id,Array.isArray(r)?r[0]:r]).catch(()=>[t.id,null])));UI.waiting=Object.fromEntries(waits); }else if(UI.mode==='demo'){const raw=localStorage.getItem(storeKey);if(raw){try{const d=JSON.parse(raw);if(d.day===dateVN())demo=d;}catch{}}}render();if(!silent)toast('Dữ liệu đã được cập nhật.');}catch(err){UI.syncError='Không thể đồng bộ dữ liệu. '+err.message;if(UI.mode==='cloud'&&!getSession()){UI.remote=null;UI.waiting={};UI.page='account';}render();if(!silent)toast(UI.syncError,'error');}}
function askConfirm(title,desc,action,params,label,danger=false){setModal({title,description:desc,confirm:label,danger,doIt:()=>execute(action,params,`Đã thực hiện: ${title.toLowerCase()}`)});}
async function actionFromClick(button){const a=button.dataset.action, id=button.dataset.id,t=findTicket(id);const privileged=['call-next','toggle-pause','checkin-form','ticket-actions','ticket-op','recall','assign-room'];if(UI.mode==='cloud'&&privileged.includes(a)&&!isStaff()){toast('Cần tài khoản nhân viên được phân quyền.','error');return;}if(a==='refresh'){await refresh();return;}if(a==='fullscreen-board'){try{await document.documentElement?.requestFullscreen?.();}catch{toast('Không thể bật toàn màn hình.','error');}return;}
if(a==='demo-staff'||a==='demo-patient'){if(UI.mode==='cloud')return;if((STAFF_PORTAL&&a!=='demo-staff')||(!STAFF_PORTAL&&a!=='demo-patient'))return;UI.role=a==='demo-staff'?'staff':'patient';toast(UI.role==='staff'?'Đang dùng vai trò nhân viên DEMO.':'Đang dùng vai trò bệnh nhân DEMO.');UI.page=a==='demo-staff'?'staff':'home';render();return;}
if(a==='pick-room'){UI.room=button.dataset.room;render();return;}
if(a==='toggle-cloud'){UI.mode=UI.mode==='demo'?'cloud':'demo';UI.page='account';UI.remote=null;await refresh(true);return;}
if(a==='auth-login-tab'||a==='auth-signup-tab'){if(STAFF_PORTAL&&a==='auth-signup-tab')return;UI.authTab=a==='auth-login-tab'?'login':'signup';UI.authError='';render();return;}
if(a==='logout'){await signOut();UI.remote=null;UI.page='account';render();toast('Đã đăng xuất.');return;}
if(a==='copy-label'){try{await navigator.clipboard.writeText(button.dataset.label);toast('Đã sao chép số thứ tự.');}catch{toast('Trình duyệt không hỗ trợ sao chép tại đây.','error');}return;}
if(a==='reset-demo'){askModalFn('Khôi phục dữ liệu giả?','Toàn bộ thay đổi trong bản demo trên trình duyệt này sẽ được thay bằng dữ liệu mẫu ban đầu.','Đặt lại',()=>{localStorage.removeItem(storeKey);demo=seedDemo();persist();render();toast('Đã khôi phục dữ liệu demo.');},true);return;}
if(a==='cancel'){if(!t)return;askConfirm('Hủy phiếu '+label(t),'Hủy phiếu đang chờ? Hệ thống sẽ không thể phục hồi phiếu bằng tài khoản bệnh nhân.','mq_cancel_my_ticket',{p_ticket_id:t.id},'Hủy phiếu',true);return;}
if(a==='checkin-code'){if(!t)return;setModal({title:'Mã check-in · '+label(t),description:'Chỉ cung cấp mã này cho nhân viên tiếp nhận. Đây là mã thử nghiệm, không phải hồ sơ bệnh án.',body:`<div style="padding:14px;background:#f0f7f8;border-radius:10px;font-size:12px;overflow-wrap:anywhere;font-weight:800;color:#126f7b" id="code-view">${E(t.qr_nonce||'Không có mã')}</div><p class="muted">Nhân viên có thể nhập mã trong mục Điều phối → Check-in mã.</p>`});return;}
if(a==='close-modal'){UI.modal=null;render();return;}
if(a==='confirm-modal'){const m=UI.modal;UI.modal=null;render();if(m?.doIt)await m.doIt();return;}
if(a==='call-next'){if(!UI.room||!can('call'))return;askConfirm('Gọi lượt tiếp theo',`Gọi bệnh nhân đang chờ tại ${rooms().find(r=>r.id===UI.room)?.title||UI.room}?`,'mq_call_next_room',{p_room_id:UI.room},'Gọi số');return;}
if(a==='toggle-pause'){if(!can('pause'))return;const paused=isPaused(UI.dept);askConfirm(paused?'Mở lại khoa':'Tạm dừng khoa',paused?'Cho phép tiếp nhận và gọi số trở lại.':'Tạm dừng cấp số và gọi số tại toàn bộ phòng trong khoa.','mq_set_department_pause',{p_department:UI.dept,p_paused:!paused,p_reason:paused?null:'Điều phối phòng khám'},paused?'Mở lại':'Tạm dừng',!paused);return;}
if(a==='checkin-form'){if(!can('checkin'))return;setModal({title:'Check-in phiếu khám',description:'Nhập mã nhận từ chính bệnh nhân. Hệ thống sẽ kiểm tra trạng thái và phân phòng.',body:'<form id="checkinForm" class="stack"><label class="field">Mã check-in<input name="nonce" required autocomplete="off" placeholder="Nhập UUID / mã trên phiếu" /></label><button type="submit" class="btn btn-primary btn-wide">Xác nhận check-in</button></form>'});return;}
if(a==='ticket-actions'){if(!t)return;const rr=rooms().filter(r=>r.department_code===t.department_code);let buttons=[['START','Bắt đầu khám'],['FINISH','Hoàn tất khám'],['SKIP','Bỏ lượt'],['RESTORE','Khôi phục phiếu'],['PRIORITY',t.is_priority?'Bỏ ưu tiên':'Đánh dấu ưu tiên']].filter(([k])=>k==='START'?t.status==='CALLED':k==='FINISH'?t.status==='SERVING':k==='SKIP'?['CALLED','WAITING'].includes(t.status):k==='RESTORE'?t.status==='SKIPPED':t.status==='WAITING');
setModal({title:'Xử lý '+label(t),description:`${t.patient_name} · ${dept(t.department_code).title} · ${statuses[t.status]?.[0]||t.status}`,body:`<div style="display:flex;flex-wrap:wrap;gap:7px;margin-top:14px">${buttons.filter(([k])=>can(k,t)).map(([k,s])=>`<button class="btn btn-ghost btn-sm" data-action="ticket-op" data-op="${k}" data-id="${t.id}">${E(s)}</button>`).join('')}${t.status==='CALLED'&&can('recall',t)?`<button class="btn btn-ghost btn-sm" data-action="recall" data-id="${t.id}">Gọi lại (${t.recall_count||0}/3)</button>`:''}</div>${t.status==='WAITING'&&t.checked_in_at&&can('transfer',t)?`<div style="margin-top:15px"><label class="field">Chuyển phòng khám<select id="modalRoom">${rr.map(r=>`<option value="${E(r.id)}" ${r.id===t.room_id?'selected':''}>${E(r.title)}</option>`).join('')}</select></label><button class="btn btn-outline btn-sm" style="margin-top:10px" data-action="assign-room" data-id="${t.id}">Xác nhận chuyển phòng</button></div>`:''}`});return;}
if(a==='ticket-op'){if(!t||!can(button.dataset.op,t))return;let op=button.dataset.op;const priority=op==='PRIORITY'?!t.is_priority:null;UI.modal=null;render();await execute('mq_change_ticket',{p_ticket_id:t.id,p_action:op,p_priority:priority},'Đã cập nhật phiếu '+label(t));return;}
if(a==='recall'){if(!t||!can('recall',t))return;UI.modal=null;render();await execute('mq_recall_ticket',{p_ticket_id:t.id},'Đã gọi lại '+label(t));return;}
if(a==='assign-room'){if(!t||!can('transfer',t))return;let roomId=document.getElementById('modalRoom')?.value;UI.modal=null;render();await execute('mq_assign_room',{p_ticket_id:t.id,p_room_id:roomId},'Đã chuyển phòng cho '+label(t));return;}
}
function askModalFn(title,description,label,fn,danger){setModal({title,description,confirm:label,danger,doIt:fn});}
document.addEventListener('click',async e=>{if(e.target.matches('.modal-backdrop')){UI.modal=null;render();return;}let nav=e.target.closest('[data-page]');if(nav){if(!navigation.some(n=>n[0]===nav.dataset.page))return;if(UI.mode==='cloud'&&!getSession()&&['book','track','reception','staff','analytics'].includes(nav.dataset.page)){UI.page='account';render();toast('Vui lòng đăng nhập để tiếp tục.','error');}else move(nav.dataset.page);return;}const b=e.target.closest('[data-action]');if(b)await actionFromClick(b);});
document.addEventListener('change',e=>{if(e.target.id==='assignmentPicker'){const a=activeAssignments(verifiedAccess()).find(x=>x.id===e.target.value);if(!a)return;UI.assignmentId=a.id;UI.dept=a.department_code;UI.room=a.room_id||rooms().find(r=>r.department_code===a.department_code)?.id||'';UI.page='work-home';render();return;}if(e.target.id==='staffDept'){UI.dept=e.target.value;UI.room=rooms().find(r=>r.department_code===UI.dept)?.id||'';render();}if(e.target.id==='staffRoom'){UI.room=e.target.value;render();}if(e.target.id==='demoName'){demo.myName=e.target.value.trim();persist();} });
document.addEventListener('input',e=>{if(e.target.id==='staffSearch'){UI.staffSearch=e.target.value;const pos=e.target.selectionStart;render();const x=document.getElementById('staffSearch');x?.focus();x?.setSelectionRange(pos,pos);}});
document.addEventListener('submit',async e=>{if(e.target.id==='bookingForm'){e.preventDefault();const fd=new FormData(e.target),n=String(fd.get('patientName')||'').trim(),d=String(fd.get('department')||'GENERAL');if(n.length<2){toast('Tên phải có ít nhất 2 ký tự.','error');return;}UI.dept=d;if(UI.mode==='demo'){demo.myName=n;}const done=await execute('mq_issue_ticket',{p_department:d,p_name:n,p_request_key:rand()},'Đã cấp số thứ tự thành công.');if(done){UI.page='track';render();}}
else if(e.target.id==='authForm'){e.preventDefault();if(UI.authBusy)return;UI.authBusy=true;UI.authError='';const submit=e.target.querySelector('button[type=submit]');const originalLabel=submit?.textContent;if(submit){submit.disabled=true;submit.setAttribute('aria-busy','true');submit.textContent='Đang xử lý…';}const fd=new FormData(e.target),email=String(fd.get('email')),pw=String(fd.get('password'));try{
 if(STAFF_PORTAL || UI.authTab==='login'){
  await signIn(email,pw);
  const data=await loadCloudData();
  const allowed=ADMIN_PORTAL?data.profile?.role==='admin':STAFF_PORTAL?data.profile?.role==='staff':data.profile?.role==='patient';
  if(!allowed){
    await signOut();UI.remote=null;UI.page='account';render();
    throw new Error(STAFF_PORTAL?'Đây không phải tài khoản nhân viên được cấp quyền. Vui lòng dùng cổng bệnh nhân.':'Đây là tài khoản nội bộ. Hãy sử dụng cổng nhân viên / quản trị.');
  }
  UI.remote=data;await refresh(true);UI.page=ADMIN_PORTAL?'admin-home':STAFF_PORTAL?'work-home':'home';render();toast('Đăng nhập thành công.');
 }else{
  const v=await signUp(email,pw);
  if(getSession()){
    await refresh(true);UI.page='account';toast('Đăng ký tài khoản bệnh nhân thành công.');
  }else{toast('Đã gửi email xác minh. Hãy mở email rồi quay lại website.');UI.authTab='login';}render();
 }
}catch(err){UI.authError=err.message==='Invalid login credentials'?'Email hoặc mật khẩu không đúng. Hãy kiểm tra tài khoản thử của MediQueue.':err.message;render();toast(UI.authError,'error');}finally{UI.authBusy=false;if(submit?.isConnected){submit.disabled=false;submit.removeAttribute('aria-busy');submit.textContent=originalLabel;}}}
else if(e.target.id==='checkinForm'){e.preventDefault();const nonce=String(new FormData(e.target).get('nonce')||'').trim();UI.modal=null;render();await execute('mq_checkin_qr',{p_nonce:nonce},'Check-in thành công.');}});
window.addEventListener('storage',e=>{if(e.key===storeKey&&UI.mode==='demo'){demo=seedDemo();render();}});
try{const bc=new BroadcastChannel('mq-demo');bc.onmessage=e=>{if(e.data?.type==='updated'&&UI.mode==='demo'){demo=seedDemo();render();}};}catch{}
setInterval(()=>{if(UI.mode==='cloud'&&getSession()&&!document.hidden)refresh(true);},15000);
if(hasCloudConfig()){
 UI.mode='cloud';let confirmed=false;
 try{confirmed=await consumeAuthRedirect();}catch(err){toast(err.message||'Liên kết xác minh email không hợp lệ.','error');}
 if(getSession()){
   try{
     const data=await loadCloudData();
     if(ADMIN_PORTAL?data.profile?.role!=='admin':STAFF_PORTAL?data.profile?.role!=='staff':data.profile?.role!=='patient'){
       await signOut();UI.remote=null;UI.page='account';render();
       toast('Tài khoản thuộc cổng khác. Vui lòng đăng nhập vào cổng phù hợp.','error');
     }else{UI.remote=data;UI.page=confirmed?'account':(ADMIN_PORTAL?'admin-home':STAFF_PORTAL?'work-home':'home');await refresh(true);if(confirmed)toast('Xác minh email thành công.');}
   }catch(err){UI.page='account';UI.remote=null;render();toast('Không thể tải tài khoản: '+err.message,'error');}
 } else{UI.page='account';render();}
}else{persist();render();}



installSidebar();
window.addEventListener('hashchange',()=>{const r=window.location.hash.slice(1);if(/^[a-z-]+$/.test(r))move(r);});

function workDashboard(){
 const a=assignment();
 if(!a)return '<section class="surface"><h1>Chưa có phân công</h1><p>Liên hệ quản trị để xác minh chức danh, khoa, phòng và ca trực.</p></section>';
 UI.dept=a.department_code;
 const rr=rooms();if(!rr.some(r=>r.id===UI.room))UI.room=a.room_id||rr[0]?.id||'';
 const k=counts(),supported=['reception','doctor','nurse','department_lead'].includes(a.job_title);
 const choices=activeAssignments(verifiedAccess());
 const picker=choices.length>1?`<label>PHÂN CÔNG ĐƯỢC CẤP<select id="assignmentPicker">${choices.map(x=>`<option value="${E(x.id)}" ${a.id===x.id?'selected':''}>${E(titles[x.job_title])} · ${E(x.department_code)} ${E(x.room_id||'')}</option>`).join('')}</select></label>`:`<strong>${E(dept(a.department_code).title||a.department_code)}${a.room_id?' · '+E(a.room_id):''}</strong>`;
 const controls=[can('call')?`<button class="btn btn-primary" data-action="call-next">Gọi lượt tiếp theo</button>`:'',can('checkin')?`<button class="btn btn-outline" data-action="checkin-form">Xác nhận check-in</button>`:'',can('pause')?`<button class="btn btn-ghost" data-action="toggle-pause">${isPaused(UI.dept)?'Mở lại khoa':'Tạm dừng khoa'}</button>`:''].join('');
 const roomPicker=rr.length>1?`<label class="field">Phòng được phép<select id="staffRoom">${rr.map(r=>`<option value="${E(r.id)}" ${r.id===UI.room?'selected':''}>${E(r.title)}</option>`).join('')}</select></label>`:'';
 const rows=tickets().filter(t=>UI.page!=='staff'||t.room_id===UI.room);
 return `<div class="workspace-heading"><div><span class="section-kicker">KHÔNG GIAN CHUYÊN MÔN</span><h1>${E(titles[a.job_title]||'Nhân viên')}</h1><p>Chỉ hiển thị nhiệm vụ thuộc phân công đã xác minh.</p></div><div class="dept-control">${picker}<small>Ca trực: ${E(fmtTime(a.valid_from))} – ${E(fmtTime(a.valid_to))} · ${UI.mode==='demo'?'Dữ liệu giả':'Supabase xác nhận'}</small></div></div><div class="kpi-row">${[['Đang chờ',supported?k.waiting:'—'],['Đang phục vụ',supported?k.active:'—'],['Đã hoàn tất',supported?k.completed:'—'],['Phòng được phân',rr.length]].map(([label,value])=>`<article class="kpi"><span>${label}</span><strong>${value}</strong><small>${supported?'Trong phạm vi dữ liệu được tải':'Chưa có API nghiệp vụ'}</small></article>`).join('')}</div><div class="workspace-grid"><section class="surface main-surface"><div class="section-top"><div><span class="section-kicker">DANH SÁCH CÔNG VIỆC</span><h2>Lượt khám trong phạm vi phân công</h2></div><span class="live-tag"><span></span>${UI.mode==='demo'?'DEMO':'DEV'}</span></div><div class="work-rows">${supported?rows.map(t=>`<div class="task-row"><div class="task-number">${E(label(t))}</div><div class="task-info"><b>${E(t.patient_name)}</b><small>${E(rooms().find(r=>r.id===t.room_id)?.title||'Chưa phân phòng')} · ${t.checked_in_at?'Đã check-in':'Chưa check-in'}</small></div>${badge(t.status)}${['START','FINISH','SKIP','RESTORE','PRIORITY','recall','transfer'].some(op=>can(op,t))?`<button class="btn btn-ghost btn-sm" data-action="ticket-actions" data-id="${t.id}">Xử lý</button>`:''}</div>`).join('')||'<p class="muted">Chưa có dữ liệu trong phạm vi được cấp.</p>':'<p class="muted">Phân hệ này chưa có API nghiệp vụ. Không có kết quả xét nghiệm, thuốc, hóa đơn hoặc dữ liệu minh họa được dùng làm dữ liệu thật.</p>'}</div></section><section class="surface side-surface"><div class="section-top"><div><span class="section-kicker">QUY TRÌNH CHUYÊN MÔN</span><h2>Chức năng được cấp</h2></div></div>${roomPicker}<div class="action-list">${controls||'<p class="muted">Chỉ đọc / chưa có thao tác được cấp cho phân hệ.</p>'}</div><div class="restricted-note">Mỗi RPC kiểm tra chức danh, khoa, phòng và thời hạn ca trực tại máy chủ.</div></section></div>`;
}
function adminDashboard(){
 if(!verifiedAccess()?.is_hospital_admin)return '<section class="surface"><h1>Không đủ quyền quản trị toàn viện</h1><p>Cần quyền quản trị riêng và phiên MFA đã xác minh.</p></section>';
 const o=UI.remote?.overview;if(!o)return '<section class="surface"><h1>Chưa có dữ liệu</h1><p>Chưa tải được báo cáo từ máy chủ.</p></section>';
 const live=o.live||[],rr=o.rooms||[];
 const head=`<div class="workspace-heading"><div><span class="section-kicker">HOSPITAL SUPER ADMIN</span><h1>Điều hành toàn viện</h1><p>Dữ liệu tổng hợp vận hành; không hiển thị danh tính bệnh nhân.</p></div><div class="admin-top-symbol">MQ<span>HOSPITAL ADMIN</span></div></div>`;
 if(['access','admin-security','audit'].includes(UI.page))return head+`<section class="surface"><h2>${UI.page==='access'?'Tài khoản & phân quyền':UI.page==='audit'?'Nhật ký & giám sát':'Kiểm tra an toàn'}</h2><p>${UI.page==='access'?'Phân công đang hiệu lực: '+Number(o.assignments_count):UI.page==='audit'?'Số sự kiện cấp/thu hồi quyền: '+Number(o.audit_count):'RLS/RPC và MFA được kiểm tra tại backend. Xem báo cáo Security Advisor được kiểm chứng trong repository.'}</p><p class="muted">Chưa triển khai API chỉnh sửa phân quyền/chi tiết nhật ký trên website. Không dùng nút giả để thay đổi dữ liệu.</p></section>`;
 return head+`<div class="kpi-row">${[['Khoa',o.departments.length],['Phòng khám',rr.length],['Đang chờ',live.reduce((v,l)=>v+l.waiting_count,0)],['Phân công hiệu lực',o.assignments_count]].map(([l,v])=>`<article class="kpi"><span>${l}</span><strong>${v}</strong><small>Dữ liệu được máy chủ tổng hợp</small></article>`).join('')}</div><section class="surface"><div class="section-top"><div><span class="section-kicker">KHOA & PHÒNG KHÁM</span><h2>Tổng quan vận hành</h2></div></div><div class="dept-list-head"><span>KHOA</span><span>PHÒNG</span><span>ĐANG CHỜ</span><span>TRẠNG THÁI</span></div>${o.departments.map(d=>`<div class="dept-list-row"><b>${E(d.title)}</b><span>${rr.filter(r=>r.department_code===d.code).length}</span><span>${Number(live.find(l=>l.department_code===d.code)?.waiting_count||0)}</span><em>${live.find(l=>l.department_code===d.code)?.is_paused?'Tạm dừng':'Hoạt động'}</em></div>`).join('')}</section>`;
}

function patientHome(){return `<span class="preview-label">KHÔNG GIAN BỆNH NHÂN</span><h1 class="preview-title">Xin chào! Hôm nay bạn muốn khám khoa nào?</h1><p class="preview-description">Đăng ký và theo dõi hành trình khám bệnh trong một giao diện đơn giản, rõ ràng và dễ sử dụng.</p><div class="preview-banner"><strong>${UI.mode==='demo'?'DEMO GIAO DIỆN':'MEDIQUEUE-DEV'}</strong><span>${UI.mode==='demo'?'Dữ liệu mô phỏng, không cấp quyền thật.':'Chỉ dùng tài khoản thử. Phiếu và trạng thái được tải theo quyền truy cập từ Supabase.'}</span></div><div class="preview-grid">${[['book','✦','Lấy số khám','Chọn chuyên khoa, đăng ký khám, nhận mã check-in và số thứ tự.'],['track','◷','Phiếu của tôi','Theo dõi thời gian chờ, phòng được phân và trạng thái gọi lượt.'],['account','♧','Thông tin cá nhân','Quản lý thông tin tài khoản và phiên đăng nhập.']].map(([page,icon,title,desc])=>`<button type="button" class="preview-card" data-page="${page}"><span class="preview-card-icon">${icon}</span><h3>${title}</h3><p>${desc}</p><div class="preview-card-meta">BỆNH NHÂN</div></button>`).join('')}</div><p class="preview-small">${UI.mode==='demo'?'Đang xem bản mô phỏng.':`Phiếu đang chờ của bạn: ${ownTickets().filter(t=>t.status==='WAITING').length}. Dữ liệu tự cập nhật khi tab hoạt động.`}</p>`;}
